BEGIN TRANSACTION;
CREATE TABLE chapters (
    id INTEGER PRIMARY KEY,
    chapter_number INTEGER UNIQUE NOT NULL,
    name_sanskrit TEXT NOT NULL,
    name_transliterated TEXT NOT NULL,
    name_meaning TEXT NOT NULL,
    summary_en TEXT,
    summary_hi TEXT,
    verses_count INTEGER NOT NULL,
    slug TEXT
);
As both armies stand ready for the battle, the mighty warrior Arjuna, on observing the warriors on both sides becomes increasingly sad and depressed due to the fear of losing his relatives and friends and the consequent sins attributed to killing his own relatives. So, he surrenders to Lord Krishna, seeking a solution. Thus, follows the wisdom of the Bhagavad Gita.','भगवद गीता का पहला अध्याय अर्जुन विशाद योग उन पात्रों और परिस्थितियों का परिचय कराता है जिनके कारण पांडवों और कौरवों के बीच महाभारत का महासंग्राम हुआ। यह अध्याय उन कारणों का वर्णन करता है जिनके कारण भगवद गीता का ईश्वरावेश हुआ। जब महाबली योद्धा अर्जुन दोनों पक्षों पर युद्ध के लिए तैयार खड़े योद्धाओं को देखते हैं तो वह अपने ही रिश्तेदारों एवं मित्रों को खोने के डर तथा फलस्वरूप पापों के कारण दुखी और उदास हो जाते हैं। इसलिए वह श्री कृष्ण को पूरी तरह से आत्मसमर्पण करते हैं। इस प्रकार, भगवद गीता के ज्ञान का प्रकाश होता है।',47,'chapter-1-arjuna-visada-yoga');
"Sankhya Yoga" can be categorized into 4 main topics - 
1. Arjuna completely surrenders himself to Lord Krishna and accepts his position as a disciple and Krishna as his Guru. He requests Krishna to guide him on how to dismiss his sorrow.
2. Explanation of the main cause of all grief, which is ignorance of the true nature of Self.
3. Karma Yoga - the discipline of selfless action without being attached to its fruits.
4. Description of a Perfect Man - One whose mind is steady and one-pointed.','भगवद गीता का दूसरा अध्याय सांख्य योग है। यह अध्याय भगवद गीता का सबसे महत्वपूर्ण अध्याय है क्योंकि इसमें भगवान श्रीकृष्ण संपूर्ण गीता की शिक्षाओं को संघनित करते हैं। यह अध्याय पूरी गीता का सार है। सांख्य योग को 4 मुख्य विषयों में वर्गीकृत किया जा सकता है - १. अर्जुन ने पूरी तरह से भगवान कृष्ण को आत्मसमर्पण किया और उन्हें अपने गुरु के रूप में स्वीकार किया। २. सभी दु:खों के मुख्य कारणों की व्याख्या, जो स्व की वास्तविक प्रकृति की अज्ञानता है। ३. कर्मयोग - अपने कर्मों के फलों से जुड़े बिना नि:स्वार्थ क्रिया का अनुशासन। ४. एक परिपूर्ण मनुष्य का विवरण - जिसका मस्तिष्क स्थिर और एक-इशारा है।',72,'chapter-2-sankhya-yoga');
CREATE TABLE lessons (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    verse_key TEXT NOT NULL,
    lesson_number INTEGER NOT NULL, -- 1 to 4
    title TEXT NOT NULL,
    description TEXT,
    total_xp INTEGER DEFAULT 50,
    FOREIGN KEY(verse_key) REFERENCES verses(verse_key)
);
CREATE TABLE questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    verse_id INTEGER NOT NULL,
    verse_key TEXT NOT NULL,
    chapter_number INTEGER NOT NULL,
    verse_number INTEGER NOT NULL,
    
    -- Duolingo Lesson Stage / Level:
    -- 1: Vocabulary & Words (Build roots)
    -- 2: Shloka Structure & Recitation (Grammar & Flow)
    -- 3: Meaning & Context (Comprehension)
    -- 4: Philosophy & Life Dilemmas (Application)
    lesson_level INTEGER NOT NULL DEFAULT 1,
    question_order INTEGER NOT NULL,
    
    -- Question Types:
    -- 'match_pairs', 'mcq_vocab', 'mcq_reverse_vocab', 'fill_blank', 
    -- 'word_order', 'speaker_context', 'translation_mcq', 
    -- 'philosophical_insight', 'life_scenario', 'true_false'
    question_type TEXT NOT NULL,
    difficulty TEXT NOT NULL CHECK(difficulty IN ('beginner', 'intermediate', 'advanced')),
    
    instruction TEXT NOT NULL,        -- e.g. "Select the correct meaning", "Fill in the blank"
    prompt TEXT NOT NULL,             -- The question prompt / sentence
    prompt_sanskrit TEXT,             -- Optional Sanskrit snippet
    
    options_json TEXT NOT NULL,       -- JSON Array of choices, or pair items
    correct_answer_json TEXT NOT NULL,-- Correct choice string, index, or match dict
    
    explanation TEXT NOT NULL,        -- Rich explanation with spiritual insight
    hint TEXT,                        -- Optional clue for learners
    xp_points INTEGER NOT NULL DEFAULT 10,
    
    FOREIGN KEY(verse_id) REFERENCES verses(id)
);

