INSERT INTO "questions" VALUES(66,1,'BG1.1',1,1,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["dhṛitarāśhtraḥ uvācha", "dharma-kṣhetre", "kuru-kṣhetre", "samavetāḥ"], "meanings": ["having gathered", "the land of dharma", "at Kurukshetra", "Dhritarashtra said"]}','{"dhṛitarāśhtraḥ uvācha": "Dhritarashtra said", "dharma-kṣhetre": "the land of dharma", "kuru-kṣhetre": "at Kurukshetra", "samavetāḥ": "having gathered"}','In verse BG1.1, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(67,1,'BG1.1',1,1,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "dhṛitarāśhtraḥ uvācha" mean in this verse?','dhṛitarāśhtraḥ uvācha','["at Kurukshetra", "having gathered", "the land of dharma", "Dhritarashtra said"]','"Dhritarashtra said"','"dhṛitarāśhtraḥ uvācha" translates directly to "Dhritarashtra said" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(68,1,'BG1.1',1,1,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "dharma-kṣhetre"?','dharma-kṣhetre','["at Kurukshetra", "the land of dharma", "Dhritarashtra said", "having gathered"]','"the land of dharma"','"dharma-kṣhetre" means "the land of dharma", a crucial term in verse BG1.1.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(69,1,'BG1.1',1,1,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "at Kurukshetra"?',NULL,'["kuru-kṣhetre", "samavetāḥ", "dhṛitarāśhtraḥ uvācha", "dharma-kṣhetre"]','"kuru-kṣhetre"','The term "kuru-kṣhetre" corresponds directly to "at Kurukshetra".','Check the word roots.',10);
INSERT INTO "questions" VALUES(70,1,'BG1.1',1,1,2,5,'fill_blank','intermediate','Fill in the missing word to complete the verse line','Complete the verse:
INSERT INTO "questions" VALUES(71,1,'BG1.1',1,1,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः।','["कुरुक्षेत्रे", "धर्मक्षेत्रे", "समवेता", "युयुत्सवः"]','["धर्मक्षेत्रे", "कुरुक्षेत्रे", "समवेता", "युयुत्सवः"]','Correct sequence: धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(72,1,'BG1.1',1,1,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.1?','धृतराष्ट्र उवाच','["Sanjaya", "Bhagavan Sri Krishna", "King Dhritarashtra", "Arjuna"]','"King Dhritarashtra"','This verse is spoken by King Dhritarashtra. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(73,1,'BG1.1',1,1,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.1?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "The King Dhritarashtra asked, \"O Sanjaya! What happened on the sacred battlefield of Kurukshetra when my people and the Pandavas gathered?\"", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"The King Dhritarashtra asked, \"O Sanjaya! What happened on the sacred battlefield of Kurukshetra when my people and the Pandavas gathered?\""','Accurate translation: "The King Dhritarashtra asked, "O Sanjaya! What happened on the sacred battlefield of Kurukshetra when my people and the Pandavas gathered?"".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(74,1,'BG1.1',1,1,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.1, King Dhritarashtra is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys King Dhritarashtra''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(75,1,'BG1.1',1,1,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','Why does Dhritarashtra distinguish between ''my sons'' (māmakāḥ) and ''the sons of Pandu'' (pāṇḍavāḥ) in this opening verse?',NULL,'["It exposed his partiality and attachment, viewing his own sons (''māmakāḥ'') as distinct from Pandu''s sons despite both being his family.", "He was simply abiding by legal terminology of the royal court.", "He had forgotten that the Pandavas were his nephews.", "He wanted to praise the Pandavas for their martial superiority."]','"It exposed his partiality and attachment, viewing his own sons (''māmakāḥ'') as distinct from Pandu''s sons despite both being his family."','Commentators like Sri Madhusudana Saraswati and Shankaracharya point out that the word ''māmakāḥ'' (my sons) exposes Dhritarashtra''s deep attachment (moha) and bias, the very root of conflict.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(76,1,'BG1.1',1,1,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: Rajiv is the CEO of a company. When evaluating two teams for funding, he secretly favors the team led by his own nephew over a far more qualified team. Which trap from verse 1.1 has Rajiv fallen into?',NULL,'["The trap of ''māmakāḥ'' (blind nepotism and egoic attachment dividing ''mine'' from ''theirs'')", "The virtue of Dharmakshetra (fostering meritocracy)", "The detachment of a Sthitaprajna", "The discipline of Karma Yoga"]','"The trap of ''māmakāḥ'' (blind nepotism and egoic attachment dividing ''mine'' from ''theirs'')"','Dhritarashtra''s question symbolizes the ego favoring ''mine'' over what is universally righteous and fair.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(77,1,'BG1.1',1,1,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','In the allegorical interpretation of the Gita, what does ''Dharmakshetra Kurukshetra'' represent?',NULL,'["Kurukshetra represents the human body and mind, where the battle between virtuous tendencies (Pandavas) and destructive desires (Kauravas) is fought every day.", "It was merely an ordinary piece of real estate with no symbolic significance.", "It signifies a sanctuary where no conflict could ever occur.", "It symbolizes political elections in ancient kingdoms."]','"Kurukshetra represents the human body and mind, where the battle between virtuous tendencies (Pandavas) and destructive desires (Kauravas) is fought every day."','Great sages (Paramahamsa Yogananda, Sri Aurobindo, Eknath Easwaran) explain that Kurukshetra is the Kshetra (field) of our own consciousness where righteousness and ego clash.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(78,1,'BG1.1',1,1,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.1?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(79,2,'BG1.2',1,2,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["sanjayaḥ uvācha", "dṛiṣhṭvā", "tu", "pāṇḍava-anīkam"], "meanings": ["but", "Sanjay said", "the Pandava army", "on observing"]}','{"sanjayaḥ uvācha": "Sanjay said", "dṛiṣhṭvā": "on observing", "tu": "but", "pāṇḍava-anīkam": "the Pandava army"}','In verse BG1.2, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(80,2,'BG1.2',1,2,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "sanjayaḥ uvācha" mean in this verse?','sanjayaḥ uvācha','["but", "the Pandava army", "on observing", "Sanjay said"]','"Sanjay said"','"sanjayaḥ uvācha" translates directly to "Sanjay said" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(81,2,'BG1.2',1,2,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "dṛiṣhṭvā"?','dṛiṣhṭvā','["on observing", "the Pandava army", "but", "Sanjay said"]','"on observing"','"dṛiṣhṭvā" means "on observing", a crucial term in verse BG1.2.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(82,2,'BG1.2',1,2,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "but"?',NULL,'["tu", "pāṇḍava-anīkam", "dṛiṣhṭvā", "sanjayaḥ uvācha"]','"tu"','The term "tu" corresponds directly to "but".','Check the word roots.',10);
INSERT INTO "questions" VALUES(83,2,'BG1.2',1,2,2,5,'fill_blank','intermediate','Fill in the missing word to complete the verse line','Complete the verse:
INSERT INTO "questions" VALUES(84,2,'BG1.2',1,2,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा।','["व्यूढं", "दुर्योधनस्तदा", "दृष्ट्वा", "पाण्डवानीकं", "तु"]','["दृष्ट्वा", "तु", "पाण्डवानीकं", "व्यूढं", "दुर्योधनस्तदा"]','Correct sequence: दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(85,2,'BG1.2',1,2,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.2?','सञ्जय उवाच','["King Dhritarashtra", "Sanjaya", "Bhagavan Sri Krishna", "Arjuna"]','"Sanjaya"','This verse is spoken by Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(86,2,'BG1.2',1,2,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.2?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya replied: \"When Prince Duryodhana saw the Pandavas'' army paraded, he approached his preceptor Guru Drona and spoke these words:"]','"Sanjaya replied: \"When Prince Duryodhana saw the Pandavas'' army paraded, he approached his preceptor Guru Drona and spoke these words:"','Accurate translation: "Sanjaya replied: "When Prince Duryodhana saw the Pandavas'' army paraded, he approached his preceptor Guru Drona and spoke these words:".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(87,2,'BG1.2',1,2,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.2, Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(88,2,'BG1.2',1,2,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.2?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(89,2,'BG1.2',1,2,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(90,2,'BG1.2',1,2,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.2?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(91,2,'BG1.2',1,2,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.2?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(92,3,'BG1.3',1,3,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["paśhya", "etām", "pāṇḍu-putrāṇām", "āchārya"], "meanings": ["of the sons of Pandu", "behold", "this", "respected teacher"]}','{"paśhya": "behold", "etām": "this", "pāṇḍu-putrāṇām": "of the sons of Pandu", "āchārya": "respected teacher"}','In verse BG1.3, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(93,3,'BG1.3',1,3,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "paśhya" mean in this verse?','paśhya','["this", "of the sons of Pandu", "behold", "respected teacher"]','"behold"','"paśhya" translates directly to "behold" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(94,3,'BG1.3',1,3,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "etām"?','etām','["respected teacher", "of the sons of Pandu", "this", "behold"]','"this"','"etām" means "this", a crucial term in verse BG1.3.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(95,3,'BG1.3',1,3,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "of the sons of Pandu"?',NULL,'["paśhya", "etām", "pāṇḍu-putrāṇām", "āchārya"]','"pāṇḍu-putrāṇām"','The term "pāṇḍu-putrāṇām" corresponds directly to "of the sons of Pandu".','Check the word roots.',10);
