INSERT INTO "questions" VALUES(97,3,'BG1.3',1,3,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।','["चमूम्", "पश्यैतां", "महतीं", "पाण्डुपुत्राणामाचार्य"]','["पश्यैतां", "पाण्डुपुत्राणामाचार्य", "महतीं", "चमूम्"]','Correct sequence: पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(98,3,'BG1.3',1,3,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.3?',NULL,'["Sanjaya", "Arjuna", "Bhagavan Sri Krishna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(99,3,'BG1.3',1,3,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.3?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Revered Father! Behold this mighty host of the Pandavas, paraded by the son of King Drupada, your wise disciple.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"Revered Father! Behold this mighty host of the Pandavas, paraded by the son of King Drupada, your wise disciple."','Accurate translation: "Revered Father! Behold this mighty host of the Pandavas, paraded by the son of King Drupada, your wise disciple.".','Identify the key actors and actions described in the Sanskrit words.',15);
