INSERT INTO "questions" VALUES(105,4,'BG1.4',1,4,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["atra", "śhūrāḥ", "mahā-iṣhu-āsāḥ", "bhīma-arjuna-samāḥ"], "meanings": ["powerful warriors", "equal to Bheem and Arjun", "great bowmen", "here"]}','{"atra": "here", "śhūrāḥ": "powerful warriors", "mahā-iṣhu-āsāḥ": "great bowmen", "bhīma-arjuna-samāḥ": "equal to Bheem and Arjun"}','In verse BG1.4, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(106,4,'BG1.4',1,4,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "atra" mean in this verse?','atra','["powerful warriors", "here", "great bowmen", "equal to Bheem and Arjun"]','"here"','"atra" translates directly to "here" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(107,4,'BG1.4',1,4,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "śhūrāḥ"?','śhūrāḥ','["here", "equal to Bheem and Arjun", "powerful warriors", "great bowmen"]','"powerful warriors"','"śhūrāḥ" means "powerful warriors", a crucial term in verse BG1.4.','Recall the verse breakdown.',10);
