INSERT INTO "questions" VALUES(110,4,'BG1.4',1,4,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','अत्र शूरा महेष्वासा भीमार्जुनसमा युधि।','["भीमार्जुनसमा", "अत्र", "शूरा", "महेष्वासा", "युधि"]','["अत्र", "शूरा", "महेष्वासा", "भीमार्जुनसमा", "युधि"]','Correct sequence: अत्र शूरा महेष्वासा भीमार्जुनसमा युधि. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(111,4,'BG1.4',1,4,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.4?',NULL,'["Arjuna", "Bhagavan Sri Krishna", "Narrator / Sanjaya", "Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(112,4,'BG1.4',1,4,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.4?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "In it are heroes and great bowmen; the equals in battle of Arjuna, Bheema, Yuyudhana, Virata, and Drupada—all great soldiers.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"In it are heroes and great bowmen; the equals in battle of Arjuna, Bheema, Yuyudhana, Virata, and Drupada—all great soldiers."','Accurate translation: "In it are heroes and great bowmen; the equals in battle of Arjuna, Bheema, Yuyudhana, Virata, and Drupada—all great soldiers.".','Identify the key actors and actions described in the Sanskrit words.',15);
