INSERT INTO "questions" VALUES(118,5,'BG1.5',1,5,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["dhṛiṣhṭaketuḥ", "chekitānaḥ", "kāśhirājaḥ", "cha"], "meanings": ["Dhrishtaketu", "Kashiraj", "and", "Chekitan"]}','{"dhṛiṣhṭaketuḥ": "Dhrishtaketu", "chekitānaḥ": "Chekitan", "kāśhirājaḥ": "Kashiraj", "cha": "and"}','In verse BG1.5, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
