INSERT INTO "questions" VALUES(120,5,'BG1.5',1,5,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "chekitānaḥ"?','chekitānaḥ','["Dhrishtaketu", "Kashiraj", "and", "Chekitan"]','"Chekitan"','"chekitānaḥ" means "Chekitan", a crucial term in verse BG1.5.','Recall the verse breakdown.',10);
