INSERT INTO "questions" VALUES(131,6,'BG1.6',1,6,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["saubhadraḥ", "draupadeyāḥ", "cha", "sarve"], "meanings": ["and", "the son of Subhadra", "all", "the sons of Draupadi"]}','{"saubhadraḥ": "the son of Subhadra", "draupadeyāḥ": "the sons of Draupadi", "cha": "and", "sarve": "all"}','In verse BG1.6, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(132,6,'BG1.6',1,6,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "saubhadraḥ" mean in this verse?','saubhadraḥ','["and", "the sons of Draupadi", "all", "the son of Subhadra"]','"the son of Subhadra"','"saubhadraḥ" translates directly to "the son of Subhadra" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(133,6,'BG1.6',1,6,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "draupadeyāḥ"?','draupadeyāḥ','["all", "the sons of Draupadi", "and", "the son of Subhadra"]','"the sons of Draupadi"','"draupadeyāḥ" means "the sons of Draupadi", a crucial term in verse BG1.6.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(134,6,'BG1.6',1,6,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "and"?',NULL,'["saubhadraḥ", "cha", "draupadeyāḥ", "sarve"]','"cha"','The term "cha" corresponds directly to "and".','Check the word roots.',10);
