INSERT INTO "questions" VALUES(136,6,'BG1.6',1,6,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्।','["उत्तमौजाश्च", "युधामन्युश्च", "विक्रान्त", "वीर्यवान्"]','["युधामन्युश्च", "विक्रान्त", "उत्तमौजाश्च", "वीर्यवान्"]','Correct sequence: युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(137,6,'BG1.6',1,6,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.6?',NULL,'["Narrator / Sanjaya", "Bhagavan Sri Krishna", "Sanjaya", "Arjuna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(138,6,'BG1.6',1,6,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.6?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Yudhamanyu, Uttamouja, Soubhadra, and the sons of Droupadi—all famous men."]','"Yudhamanyu, Uttamouja, Soubhadra, and the sons of Droupadi—all famous men."','Accurate translation: "Yudhamanyu, Uttamouja, Soubhadra, and the sons of Droupadi—all famous men.".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(139,6,'BG1.6',1,6,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.6, Narrator / Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Narrator / Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(140,6,'BG1.6',1,6,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.6?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(141,6,'BG1.6',1,6,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
