INSERT INTO "questions" VALUES(180,9,'BG1.9',1,9,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(181,9,'BG1.9',1,9,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.9?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(182,9,'BG1.9',1,9,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.9?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(183,10,'BG1.10',1,10,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["aparyāptam", "tat", "asmākam", "balam"], "meanings": ["unlimited", "ours", "strength", "that"]}','{"aparyāptam": "unlimited", "tat": "that", "asmākam": "ours", "balam": "strength"}','In verse BG1.10, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(184,10,'BG1.10',1,10,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "aparyāptam" mean in this verse?','aparyāptam','["that", "ours", "strength", "unlimited"]','"unlimited"','"aparyāptam" translates directly to "unlimited" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(185,10,'BG1.10',1,10,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "tat"?','tat','["strength", "unlimited", "ours", "that"]','"that"','"tat" means "that", a crucial term in verse BG1.10.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(186,10,'BG1.10',1,10,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "ours"?',NULL,'["balam", "aparyāptam", "tat", "asmākam"]','"asmākam"','The term "asmākam" corresponds directly to "ours".','Check the word roots.',10);
