INSERT INTO "questions" VALUES(188,10,'BG1.10',1,10,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।','["भीष्माभिरक्षितम्", "बलं", "तदस्माकं", "अपर्याप्तं"]','["अपर्याप्तं", "तदस्माकं", "बलं", "भीष्माभिरक्षितम्"]','Correct sequence: अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(189,10,'BG1.10',1,10,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.10?',NULL,'["Arjuna", "Sanjaya", "Narrator / Sanjaya", "Bhagavan Sri Krishna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(190,10,'BG1.10',1,10,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.10?',NULL,'["Yet our army seems weaker, though commanded by Bhishma; their army seems stronger, though commanded by Bhima.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"Yet our army seems weaker, though commanded by Bhishma; their army seems stronger, though commanded by Bhima."','Accurate translation: "Yet our army seems weaker, though commanded by Bhishma; their army seems stronger, though commanded by Bhima.".','Identify the key actors and actions described in the Sanskrit words.',15);
