INSERT INTO "questions" VALUES(203,11,'BG1.11',1,11,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.11?',NULL,'["Therefore, let the rank and file stand firm in their posts according to battalions, and all you generals around Bheeshma.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"Therefore, let the rank and file stand firm in their posts according to battalions, and all you generals around Bheeshma."','Accurate translation: "Therefore, let the rank and file stand firm in their posts according to battalions, and all you generals around Bheeshma.".','Identify the key actors and actions described in the Sanskrit words.',15);
