INSERT INTO "questions" VALUES(216,12,'BG1.12',1,12,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.12?',NULL,'["Then, to enliven his spirits, the brave Grandfather Bheeshma, the eldest of the Kuru clan, blew his conch, its sound resembling that of a lion''s roar.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"Then, to enliven his spirits, the brave Grandfather Bheeshma, the eldest of the Kuru clan, blew his conch, its sound resembling that of a lion''s roar."','Accurate translation: "Then, to enliven his spirits, the brave Grandfather Bheeshma, the eldest of the Kuru clan, blew his conch, its sound resembling that of a lion''s roar.".','Identify the key actors and actions described in the Sanskrit words.',15);
