INSERT INTO "questions" VALUES(240,14,'BG1.14',1,14,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ।','["महति", "श्वेतैर्हयैर्युक्ते", "स्यन्दने", "स्थितौ", "ततः"]','["ततः", "श्वेतैर्हयैर्युक्ते", "महति", "स्यन्दने", "स्थितौ"]','Correct sequence: ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
