INSERT INTO "questions" VALUES(248,15,'BG1.15',1,15,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["pāñchajanyam", "hṛiṣhīka-īśhaḥ", "devadattam", "dhanam-jayaḥ"], "meanings": ["the conch shell named Devadutta", "Shree Krishna, the Lord of the mind and senses", "Arjun, the winner of wealth", "the conch shell named Panchajanya"]}','{"pāñchajanyam": "the conch shell named Panchajanya", "hṛiṣhīka-īśhaḥ": "Shree Krishna, the Lord of the mind and senses", "devadattam": "the conch shell named Devadutta", "dhanam-jayaḥ": "Arjun, the winner of wealth"}','In verse BG1.15, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(249,15,'BG1.15',1,15,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "pāñchajanyam" mean in this verse?','pāñchajanyam','["the conch shell named Panchajanya", "the conch shell named Devadutta", "Shree Krishna, the Lord of the mind and senses", "Arjun, the winner of wealth"]','"the conch shell named Panchajanya"','"pāñchajanyam" translates directly to "the conch shell named Panchajanya" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(250,15,'BG1.15',1,15,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "hṛiṣhīka-īśhaḥ"?','hṛiṣhīka-īśhaḥ','["Shree Krishna, the Lord of the mind and senses", "Arjun, the winner of wealth", "the conch shell named Devadutta", "the conch shell named Panchajanya"]','"Shree Krishna, the Lord of the mind and senses"','"hṛiṣhīka-īśhaḥ" means "Shree Krishna, the Lord of the mind and senses", a crucial term in verse BG1.15.','Recall the verse breakdown.',10);
