INSERT INTO "questions" VALUES(253,15,'BG1.15',1,15,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः।','["हृषीकेशो", "पाञ्चजन्यं", "देवदत्तं", "धनंजयः"]','["पाञ्चजन्यं", "हृषीकेशो", "देवदत्तं", "धनंजयः"]','Correct sequence: पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
