INSERT INTO "questions" VALUES(274,17,'BG1.17',1,17,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["kāśhyaḥ", "cha", "parama-iṣhu-āsaḥ", "śhikhaṇḍī"], "meanings": ["and", "King of Kashi", "Shikhandi", "the excellent archer"]}','{"kāśhyaḥ": "King of Kashi", "cha": "and", "parama-iṣhu-āsaḥ": "the excellent archer", "śhikhaṇḍī": "Shikhandi"}','In verse BG1.17, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(275,17,'BG1.17',1,17,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "kāśhyaḥ" mean in this verse?','kāśhyaḥ','["Shikhandi", "the excellent archer", "King of Kashi", "and"]','"King of Kashi"','"kāśhyaḥ" translates directly to "King of Kashi" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(276,17,'BG1.17',1,17,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "cha"?','cha','["and", "King of Kashi", "the excellent archer", "Shikhandi"]','"and"','"cha" means "and", a crucial term in verse BG1.17.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(277,17,'BG1.17',1,17,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "the excellent archer"?',NULL,'["cha", "śhikhaṇḍī", "parama-iṣhu-āsaḥ", "kāśhyaḥ"]','"parama-iṣhu-āsaḥ"','The term "parama-iṣhu-āsaḥ" corresponds directly to "the excellent archer".','Check the word roots.',10);
INSERT INTO "questions" VALUES(278,17,'BG1.17',1,17,2,5,'fill_blank','intermediate','Fill in the missing word to complete the verse line','Complete the verse:
INSERT INTO "questions" VALUES(279,17,'BG1.17',1,17,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','काश्यश्च परमेष्वासः शिखण्डी च महारथः।','["च", "परमेष्वासः", "शिखण्डी", "काश्यश्च", "महारथः"]','["काश्यश्च", "परमेष्वासः", "शिखण्डी", "च", "महारथः"]','Correct sequence: काश्यश्च परमेष्वासः शिखण्डी च महारथः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(280,17,'BG1.17',1,17,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.17?',NULL,'["Narrator / Sanjaya", "Sanjaya", "Arjuna", "Bhagavan Sri Krishna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(281,17,'BG1.17',1,17,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.17?',NULL,'["Corrected: And the Maharaja of Benares, the great archer, Shikhandi, the great soldier, Dhrishtayumna, Virata, and Satyaki, the invincible one,", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"Corrected: And the Maharaja of Benares, the great archer, Shikhandi, the great soldier, Dhrishtayumna, Virata, and Satyaki, the invincible one,"','Accurate translation: "Corrected: And the Maharaja of Benares, the great archer, Shikhandi, the great soldier, Dhrishtayumna, Virata, and Satyaki, the invincible one,".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(282,17,'BG1.17',1,17,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.17, Narrator / Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Narrator / Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(283,17,'BG1.17',1,17,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.17?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(284,17,'BG1.17',1,17,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
