INSERT INTO "questions" VALUES(294,18,'BG1.18',1,18,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.18?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "And, O King! Drupada''s sons, Droupadi''s sons, and the great soldier Soubhadra blew their conches."]','"And, O King! Drupada''s sons, Droupadi''s sons, and the great soldier Soubhadra blew their conches."','Accurate translation: "And, O King! Drupada''s sons, Droupadi''s sons, and the great soldier Soubhadra blew their conches.".','Identify the key actors and actions described in the Sanskrit words.',15);
