INSERT INTO "questions" VALUES(307,19,'BG1.19',1,19,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.19?',NULL,'["The tumult rent the hearts of the sons of Dhritarashtra, shaking heaven and earth with its echoing violence.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"The tumult rent the hearts of the sons of Dhritarashtra, shaking heaven and earth with its echoing violence."','Accurate translation: "The tumult rent the hearts of the sons of Dhritarashtra, shaking heaven and earth with its echoing violence.".','Identify the key actors and actions described in the Sanskrit words.',15);
