INSERT INTO "questions" VALUES(318,20,'BG1.20',1,20,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः।','["व्यवस्थितान्", "अथ", "दृष्ट्वा", "धार्तराष्ट्रान्कपिध्वजः"]','["अथ", "व्यवस्थितान्", "दृष्ट्वा", "धार्तराष्ट्रान्कपिध्वजः"]','Correct sequence: अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(319,20,'BG1.20',1,20,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.20?',NULL,'["Bhagavan Sri Krishna", "Sanjaya", "Arjuna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(320,20,'BG1.20',1,20,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.20?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Then, upon beholding the sons of Dhritarashtra, drawn up on the battlefield, ready to fight, Arjuna, whose flag bore the image of Hanuman,", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"Then, upon beholding the sons of Dhritarashtra, drawn up on the battlefield, ready to fight, Arjuna, whose flag bore the image of Hanuman,"','Accurate translation: "Then, upon beholding the sons of Dhritarashtra, drawn up on the battlefield, ready to fight, Arjuna, whose flag bore the image of Hanuman,".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(321,20,'BG1.20',1,20,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.20, Narrator / Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Narrator / Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(322,20,'BG1.20',1,20,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.20?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(323,20,'BG1.20',1,20,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(324,20,'BG1.20',1,20,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.20?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(325,20,'BG1.20',1,20,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.20?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(326,21,'BG1.21',1,21,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["arjunaḥ uvācha", "senayoḥ", "ubhayoḥ", "madhye"], "meanings": ["both", "in the middle", "armies", "Arjun said"]}','{"arjunaḥ uvācha": "Arjun said", "senayoḥ": "armies", "ubhayoḥ": "both", "madhye": "in the middle"}','In verse BG1.21, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(327,21,'BG1.21',1,21,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "arjunaḥ uvācha" mean in this verse?','arjunaḥ uvācha','["armies", "in the middle", "Arjun said", "both"]','"Arjun said"','"arjunaḥ uvācha" translates directly to "Arjun said" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(328,21,'BG1.21',1,21,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "senayoḥ"?','senayoḥ','["in the middle", "Arjun said", "both", "armies"]','"armies"','"senayoḥ" means "armies", a crucial term in verse BG1.21.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(329,21,'BG1.21',1,21,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "both"?',NULL,'["ubhayoḥ", "senayoḥ", "madhye", "arjunaḥ uvācha"]','"ubhayoḥ"','The term "ubhayoḥ" corresponds directly to "both".','Check the word roots.',10);
