INSERT INTO "questions" VALUES(331,21,'BG1.21',1,21,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','हृषीकेशं तदा वाक्यमिदमाह महीपते।','["हृषीकेशं", "तदा", "महीपते", "वाक्यमिदमाह"]','["हृषीकेशं", "तदा", "वाक्यमिदमाह", "महीपते"]','Correct sequence: हृषीकेशं तदा वाक्यमिदमाह महीपते. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(332,21,'BG1.21',1,21,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.21?','अर्जुन उवाच','["Arjuna", "Bhagavan Sri Krishna", "Sanjaya", "King Dhritarashtra"]','"Arjuna"','This verse is spoken by Arjuna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(333,21,'BG1.21',1,21,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.21?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Raising his bow, he spoke this to the Lord Shri Krishna: O Infallible Lord of the earth! Please draw up my chariot between the two armies.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"Raising his bow, he spoke this to the Lord Shri Krishna: O Infallible Lord of the earth! Please draw up my chariot between the two armies."','Accurate translation: "Raising his bow, he spoke this to the Lord Shri Krishna: O Infallible Lord of the earth! Please draw up my chariot between the two armies.".','Identify the key actors and actions described in the Sanskrit words.',15);
