INSERT INTO "questions" VALUES(345,22,'BG1.22',1,22,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.22?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "So that I may observe those who must fight on my side and those who must fight against me.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"So that I may observe those who must fight on my side and those who must fight against me."','Accurate translation: "So that I may observe those who must fight on my side and those who must fight against me.".','Identify the key actors and actions described in the Sanskrit words.',15);
