INSERT INTO "questions" VALUES(351,23,'BG1.23',1,23,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["yotsyamānān", "avekṣhe aham", "ye", "ete"], "meanings": ["those", "who", "I desire to see", "those who have come to fight"]}','{"yotsyamānān": "those who have come to fight", "avekṣhe aham": "I desire to see", "ye": "who", "ete": "those"}','In verse BG1.23, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
