INSERT INTO "questions" VALUES(364,24,'BG1.24',1,24,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["sañjayaḥ uvācha", "evam", "uktaḥ", "hṛiṣhīkeśhaḥ"], "meanings": ["addressed", "Sanjay said", "thus", "Shree Krishna, the Lord of the senses"]}','{"sañjayaḥ uvācha": "Sanjay said", "evam": "thus", "uktaḥ": "addressed", "hṛiṣhīkeśhaḥ": "Shree Krishna, the Lord of the senses"}','In verse BG1.24, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
