INSERT INTO "questions" VALUES(382,25,'BG1.25',1,25,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्।','["सर्वेषां", "महीक्षिताम्", "भीष्मद्रोणप्रमुखतः", "च"]','["भीष्मद्रोणप्रमुखतः", "सर्वेषां", "च", "महीक्षिताम्"]','Correct sequence: भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(383,25,'BG1.25',1,25,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.25?','भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्।','["Sanjaya", "Bhagavan Sri Krishna", "Arjuna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(384,25,'BG1.25',1,25,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.25?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Where Bheeshma and Drona had led all the rulers of the earth, they spoke thus: O Arjuna! Behold, these members of the family of Kuru are assembled."]','"Where Bheeshma and Drona had led all the rulers of the earth, they spoke thus: O Arjuna! Behold, these members of the family of Kuru are assembled."','Accurate translation: "Where Bheeshma and Drona had led all the rulers of the earth, they spoke thus: O Arjuna! Behold, these members of the family of Kuru are assembled.".','Identify the key actors and actions described in the Sanskrit words.',15);
