INSERT INTO "questions" VALUES(395,26,'BG1.26',1,26,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','तत्रापश्यत्स्थितान्पार्थः पितृ़नथ पितामहान्।','["तत्रापश्यत्स्थितान्पार्थः", "पितामहान्", "पितृ़नथ"]','["तत्रापश्यत्स्थितान्पार्थः", "पितृ़नथ", "पितामहान्"]','Correct sequence: तत्रापश्यत्स्थितान्पार्थः पितृ़नथ पितामहान्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
