INSERT INTO "questions" VALUES(403,27,'BG1.27',1,27,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["tān", "samīkṣhya", "saḥ", "kaunteyaḥ"], "meanings": ["on seeing", "Arjun, the son of Kunti", "these", "they"]}','{"tān": "these", "samīkṣhya": "on seeing", "saḥ": "they", "kaunteyaḥ": "Arjun, the son of Kunti"}','In verse BG1.27, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
