INSERT INTO "questions" VALUES(415,28,'BG1.28',1,28,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["arjunaḥ uvācha", "dṛiṣhṭvā", "imam", "sva-janam"], "meanings": ["on seeing", "Arjun said", "kinsmen", "these"]}','{"arjunaḥ uvācha": "Arjun said", "dṛiṣhṭvā": "on seeing", "imam": "these", "sva-janam": "kinsmen"}','In verse BG1.28, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(416,28,'BG1.28',1,28,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "arjunaḥ uvācha" mean in this verse?','arjunaḥ uvācha','["Arjun said", "on seeing", "kinsmen", "these"]','"Arjun said"','"arjunaḥ uvācha" translates directly to "Arjun said" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(417,28,'BG1.28',1,28,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "dṛiṣhṭvā"?','dṛiṣhṭvā','["these", "on seeing", "Arjun said", "kinsmen"]','"on seeing"','"dṛiṣhṭvā" means "on seeing", a crucial term in verse BG1.28.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(418,28,'BG1.28',1,28,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "these"?',NULL,'["sva-janam", "imam", "arjunaḥ uvācha", "dṛiṣhṭvā"]','"imam"','The term "imam" corresponds directly to "these".','Check the word roots.',10);
INSERT INTO "questions" VALUES(419,28,'BG1.28',1,28,2,5,'fill_blank','intermediate','Fill in the missing word to complete the verse line','Complete the verse:
INSERT INTO "questions" VALUES(420,28,'BG1.28',1,28,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','कृपया परयाऽऽविष्टो विषीदन्निदमब्रवीत्।','["विषीदन्निदमब्रवीत्", "परयाऽऽविष्टो", "कृपया"]','["कृपया", "परयाऽऽविष्टो", "विषीदन्निदमब्रवीत्"]','Correct sequence: कृपया परयाऽऽविष्टो विषीदन्निदमब्रवीत्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(421,28,'BG1.28',1,28,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.28?','अर्जुन उवाच','["Sanjaya", "King Dhritarashtra", "Bhagavan Sri Krishna", "Arjuna"]','"Arjuna"','This verse is spoken by Arjuna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(422,28,'BG1.28',1,28,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.28?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Correction: And his heart melted with pity, and sadly he spoke: \"O my Lord! When I see all these, my own people, thirsting for battle,"]','"Correction: And his heart melted with pity, and sadly he spoke: \"O my Lord! When I see all these, my own people, thirsting for battle,"','Accurate translation: "Correction: And his heart melted with pity, and sadly he spoke: "O my Lord! When I see all these, my own people, thirsting for battle,".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(423,28,'BG1.28',1,28,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.28, Arjuna is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Arjuna''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(424,28,'BG1.28',1,28,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.28?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(425,28,'BG1.28',1,28,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(426,28,'BG1.28',1,28,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.28?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(427,28,'BG1.28',1,28,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.28?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(428,29,'BG1.29',1,29,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["sīdanti", "mama", "gātrāṇi", "mukham"], "meanings": ["my", "quivering", "limbs", "mouth"]}','{"sīdanti": "quivering", "mama": "my", "gātrāṇi": "limbs", "mukham": "mouth"}','In verse BG1.29, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
