INSERT INTO "questions" VALUES(430,29,'BG1.29',1,29,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "mama"?','mama','["my", "limbs", "mouth", "quivering"]','"my"','"mama" means "my", a crucial term in verse BG1.29.','Recall the verse breakdown.',10);
