INSERT INTO "questions" VALUES(433,29,'BG1.29',1,29,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','सीदन्ति मम गात्राणि मुखं च परिशुष्यति।','["मम", "च", "सीदन्ति", "मुखं", "गात्राणि"]','["सीदन्ति", "मम", "गात्राणि", "मुखं", "च"]','Correct sequence: सीदन्ति मम गात्राणि मुखं च. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(434,29,'BG1.29',1,29,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.29?',NULL,'["Sanjaya", "Arjuna", "Bhagavan Sri Krishna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(435,29,'BG1.29',1,29,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.29?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "My limbs are failing me, my throat is parched, my body is trembling, and my hair is standing on end.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"My limbs are failing me, my throat is parched, my body is trembling, and my hair is standing on end."','Accurate translation: "My limbs are failing me, my throat is parched, my body is trembling, and my hair is standing on end.".','Identify the key actors and actions described in the Sanskrit words.',15);
