INSERT INTO "questions" VALUES(446,30,'BG1.30',1,30,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।','["परिदह्यते", "हस्तात्त्वक्चैव", "स्रंसते", "गाण्डीवं"]','["गाण्डीवं", "स्रंसते", "हस्तात्त्वक्चैव", "परिदह्यते"]','Correct sequence: गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
