INSERT INTO "questions" VALUES(448,30,'BG1.30',1,30,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.30?',NULL,'["The bow Gandiva slips from my hand, and my skin burns. I cannot remain still, for my mind is in tumult.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"The bow Gandiva slips from my hand, and my skin burns. I cannot remain still, for my mind is in tumult."','Accurate translation: "The bow Gandiva slips from my hand, and my skin burns. I cannot remain still, for my mind is in tumult.".','Identify the key actors and actions described in the Sanskrit words.',15);
