INSERT INTO "questions" VALUES(466,31,'BG1.31',1,31,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.31?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(467,32,'BG1.32',1,32,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["na", "kāṅkṣhe", "vijayam", "kṛiṣhṇa"], "meanings": ["victory", "nor", "Krishna", "do I desire"]}','{"na": "nor", "kāṅkṣhe": "do I desire", "vijayam": "victory", "kṛiṣhṇa": "Krishna"}','In verse BG1.32, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(468,32,'BG1.32',1,32,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "na" mean in this verse?','na','["victory", "nor", "Krishna", "do I desire"]','"nor"','"na" translates directly to "nor" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(469,32,'BG1.32',1,32,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "kāṅkṣhe"?','kāṅkṣhe','["do I desire", "Krishna", "nor", "victory"]','"do I desire"','"kāṅkṣhe" means "do I desire", a crucial term in verse BG1.32.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(470,32,'BG1.32',1,32,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "victory"?',NULL,'["na", "vijayam", "kāṅkṣhe", "kṛiṣhṇa"]','"vijayam"','The term "vijayam" corresponds directly to "victory".','Check the word roots.',10);
