INSERT INTO "questions" VALUES(472,32,'BG1.32',1,32,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च।','["काङ्क्षे", "न", "विजयं", "न", "कृष्ण"]','["न", "काङ्क्षे", "विजयं", "कृष्ण", "न"]','Correct sequence: न काङ्क्षे विजयं कृष्ण न. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(473,32,'BG1.32',1,32,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.32?',NULL,'["Bhagavan Sri Krishna", "Arjuna", "Sanjaya", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(474,32,'BG1.32',1,32,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.32?',NULL,'["Ah, my Lord! I do not crave victory, nor a kingdom, nor any pleasure. What would a kingdom, happiness, or life be to me?", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"Ah, my Lord! I do not crave victory, nor a kingdom, nor any pleasure. What would a kingdom, happiness, or life be to me?"','Accurate translation: "Ah, my Lord! I do not crave victory, nor a kingdom, nor any pleasure. What would a kingdom, happiness, or life be to me?".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(475,32,'BG1.32',1,32,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.32, Narrator / Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Narrator / Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(476,32,'BG1.32',1,32,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.32?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
