INSERT INTO "questions" VALUES(487,33,'BG1.33',1,33,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.33?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "When those for whose sake I desire these things stand here, about to sacrifice their property and lives:"]','"When those for whose sake I desire these things stand here, about to sacrifice their property and lives:"','Accurate translation: "When those for whose sake I desire these things stand here, about to sacrifice their property and lives:".','Identify the key actors and actions described in the Sanskrit words.',15);
