INSERT INTO "questions" VALUES(498,34,'BG1.34',1,34,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','आचार्याः पितरः पुत्रास्तथैव च पितामहाः।','["पितामहाः", "आचार्याः", "पुत्रास्तथैव", "च", "पितरः"]','["आचार्याः", "पितरः", "पुत्रास्तथैव", "च", "पितामहाः"]','Correct sequence: आचार्याः पितरः पुत्रास्तथैव च पितामहाः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(499,34,'BG1.34',1,34,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.34?',NULL,'["Arjuna", "Sanjaya", "Narrator / Sanjaya", "Bhagavan Sri Krishna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(500,34,'BG1.34',1,34,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.34?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "O slayer of Mandhu (Krsna)! I do not desire to slay these men, even though they slay me, not even for the sake of the kingdom of the three worlds, let alone for the sake of the earth.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"O slayer of Mandhu (Krsna)! I do not desire to slay these men, even though they slay me, not even for the sake of the kingdom of the three worlds, let alone for the sake of the earth."','Accurate translation: "O slayer of Mandhu (Krsna)! I do not desire to slay these men, even though they slay me, not even for the sake of the kingdom of the three worlds, let alone for the sake of the earth.".','Identify the key actors and actions described in the Sanskrit words.',15);
