INSERT INTO "questions" VALUES(511,35,'BG1.35',1,35,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।','["हन्तुमिच्छामि", "मधुसूदन", "घ्नतोऽपि", "एतान्न"]','["एतान्न", "हन्तुमिच्छामि", "घ्नतोऽपि", "मधुसूदन"]','Correct sequence: एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
