INSERT INTO "questions" VALUES(521,36,'BG1.36',1,36,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "dhārtarāṣhṭrān"?','dhārtarāṣhṭrān','["our", "by killing", "what", "the sons of Dhritarashtra"]','"the sons of Dhritarashtra"','"dhārtarāṣhṭrān" means "the sons of Dhritarashtra", a crucial term in verse BG1.36.','Recall the verse breakdown.',10);
