INSERT INTO "questions" VALUES(524,36,'BG1.36',1,36,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन।','["प्रीतिः", "निहत्य", "स्याज्जनार्दन", "का", "धार्तराष्ट्रान्नः"]','["निहत्य", "धार्तराष्ट्रान्नः", "का", "प्रीतिः", "स्याज्जनार्दन"]','Correct sequence: निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(525,36,'BG1.36',1,36,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.36?',NULL,'["Bhagavan Sri Krishna", "Narrator / Sanjaya", "Arjuna", "Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(526,36,'BG1.36',1,36,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.36?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "My Lord! What happiness can come from the death of these sons of Dhritarashtra? We shall be committing a sin if we kill these desperate men.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"My Lord! What happiness can come from the death of these sons of Dhritarashtra? We shall be committing a sin if we kill these desperate men."','Accurate translation: "My Lord! What happiness can come from the death of these sons of Dhritarashtra? We shall be committing a sin if we kill these desperate men.".','Identify the key actors and actions described in the Sanskrit words.',15);
