INSERT INTO "questions" VALUES(573,40,'BG1.40',1,40,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "praṇaśhyanti"?','praṇaśhyanti','["eternal", "are vanquished", "family traditions", "in the destruction of a dynasty"]','"are vanquished"','"praṇaśhyanti" means "are vanquished", a crucial term in verse BG1.40.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(574,40,'BG1.40',1,40,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "family traditions"?',NULL,'["kula-dharmāḥ", "praṇaśhyanti", "kula-kṣhaye", "sanātanāḥ"]','"kula-dharmāḥ"','The term "kula-dharmāḥ" corresponds directly to "family traditions".','Check the word roots.',10);
