INSERT INTO "questions" VALUES(610,43,'BG1.43',1,43,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["doṣhaiḥ", "etaiḥ", "kula-ghnānām", "varṇa-saṅkara"], "meanings": ["through evil deeds", "these", "of those who destroy the family", "unwanted progeny"]}','{"doṣhaiḥ": "through evil deeds", "etaiḥ": "these", "kula-ghnānām": "of those who destroy the family", "varṇa-saṅkara": "unwanted progeny"}','In verse BG1.43, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(611,43,'BG1.43',1,43,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "doṣhaiḥ" mean in this verse?','doṣhaiḥ','["these", "through evil deeds", "of those who destroy the family", "unwanted progeny"]','"through evil deeds"','"doṣhaiḥ" translates directly to "through evil deeds" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(612,43,'BG1.43',1,43,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "etaiḥ"?','etaiḥ','["of those who destroy the family", "unwanted progeny", "these", "through evil deeds"]','"these"','"etaiḥ" means "these", a crucial term in verse BG1.43.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(613,43,'BG1.43',1,43,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "of those who destroy the family"?',NULL,'["etaiḥ", "doṣhaiḥ", "kula-ghnānām", "varṇa-saṅkara"]','"kula-ghnānām"','The term "kula-ghnānām" corresponds directly to "of those who destroy the family".','Check the word roots.',10);
INSERT INTO "questions" VALUES(614,43,'BG1.43',1,43,2,5,'fill_blank','intermediate','Fill in the missing word to complete the verse line','Complete the verse:
INSERT INTO "questions" VALUES(615,43,'BG1.43',1,43,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः।','["कुलघ्नानां", "वर्णसङ्करकारकैः", "दोषैरेतैः"]','["दोषैरेतैः", "कुलघ्नानां", "वर्णसङ्करकारकैः"]','Correct sequence: दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(616,43,'BG1.43',1,43,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.43?',NULL,'["Sanjaya", "Arjuna", "Bhagavan Sri Krishna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(617,43,'BG1.43',1,43,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.43?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Correction: By the destruction of our lineage and the pollution of our blood, ancient class traditions and family purity alike perish.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"Correction: By the destruction of our lineage and the pollution of our blood, ancient class traditions and family purity alike perish."','Accurate translation: "Correction: By the destruction of our lineage and the pollution of our blood, ancient class traditions and family purity alike perish.".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(618,43,'BG1.43',1,43,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.43, Narrator / Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Narrator / Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(619,43,'BG1.43',1,43,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.43?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(620,43,'BG1.43',1,43,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(621,43,'BG1.43',1,43,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.43?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(622,43,'BG1.43',1,43,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.43?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
