INSERT INTO "questions" VALUES(656,46,'BG1.46',1,46,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.46?',NULL,'["If, on the contrary, the sons of Dhritarashtra, with weapons in hand, should slay me, unarmed and unresisting, surely that would be better for my welfare!", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"If, on the contrary, the sons of Dhritarashtra, with weapons in hand, should slay me, unarmed and unresisting, surely that would be better for my welfare!"','Accurate translation: "If, on the contrary, the sons of Dhritarashtra, with weapons in hand, should slay me, unarmed and unresisting, surely that would be better for my welfare!".','Identify the key actors and actions described in the Sanskrit words.',15);
