INSERT INTO "questions" VALUES(658,46,'BG1.46',1,46,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.46?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(659,46,'BG1.46',1,46,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(660,46,'BG1.46',1,46,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.46?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(661,46,'BG1.46',1,46,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.46?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "questions" VALUES(662,47,'BG1.47',1,47,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["sañjayaḥ uvācha", "evam uktvā", "arjunaḥ", "saṅkhye"], "meanings": ["speaking thus", "in the battlefield", "Arjun", "Sanjay said"]}','{"sañjayaḥ uvācha": "Sanjay said", "evam uktvā": "speaking thus", "arjunaḥ": "Arjun", "saṅkhye": "in the battlefield"}','In verse BG1.47, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(663,47,'BG1.47',1,47,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "sañjayaḥ uvācha" mean in this verse?','sañjayaḥ uvācha','["speaking thus", "in the battlefield", "Arjun", "Sanjay said"]','"Sanjay said"','"sañjayaḥ uvācha" translates directly to "Sanjay said" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(664,47,'BG1.47',1,47,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "evam uktvā"?','evam uktvā','["Arjun", "speaking thus", "in the battlefield", "Sanjay said"]','"speaking thus"','"evam uktvā" means "speaking thus", a crucial term in verse BG1.47.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(665,47,'BG1.47',1,47,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "Arjun"?',NULL,'["sañjayaḥ uvācha", "evam uktvā", "saṅkhye", "arjunaḥ"]','"arjunaḥ"','The term "arjunaḥ" corresponds directly to "Arjun".','Check the word roots.',10);
INSERT INTO "questions" VALUES(666,47,'BG1.47',1,47,2,5,'fill_blank','intermediate','Fill in the missing word to complete the verse line','Complete the verse:
INSERT INTO "questions" VALUES(667,47,'BG1.47',1,47,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','एवमुक्त्वाऽर्जुनः संख्ये रथोपस्थ उपाविशत्।','["एवमुक्त्वाऽर्जुनः", "उपाविशत्", "रथोपस्थ", "संख्ये"]','["एवमुक्त्वाऽर्जुनः", "संख्ये", "रथोपस्थ", "उपाविशत्"]','Correct sequence: एवमुक्त्वाऽर्जुनः संख्ये रथोपस्थ उपाविशत्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
INSERT INTO "questions" VALUES(668,47,'BG1.47',1,47,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG1.47?','सञ्जय उवाच','["Sanjaya", "Arjuna", "Bhagavan Sri Krishna", "King Dhritarashtra"]','"Sanjaya"','This verse is spoken by Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(669,47,'BG1.47',1,47,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG1.47?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya said: \"Having spoken thus, Arjuna sank into the seat of his chariot, discarding his bow and arrow, overwhelmed with grief in the midst of the armies.\""]','"Sanjaya said: \"Having spoken thus, Arjuna sank into the seat of his chariot, discarding his bow and arrow, overwhelmed with grief in the midst of the armies.\""','Accurate translation: "Sanjaya said: "Having spoken thus, Arjuna sank into the seat of his chariot, discarding his bow and arrow, overwhelmed with grief in the midst of the armies."".','Identify the key actors and actions described in the Sanskrit words.',15);
INSERT INTO "questions" VALUES(670,47,'BG1.47',1,47,3,10,'true_false','beginner','Evaluate the statement as True or False','True or False: "In verse BG1.47, Sanjaya is expressing an inquiry or observation regarding the battlefield."',NULL,'["True", "False"]','"True"','True. This shloka directly conveys Sanjaya''s focus and psychological state at this point of the epic.','Reflect on who spoke and the setting.',10);
INSERT INTO "questions" VALUES(671,47,'BG1.47',1,47,4,11,'philosophical_insight','intermediate','Select the deepest philosophical interpretation','What deeper psychological reality is mirrored in BG 1.47?',NULL,'["It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha).", "It is merely a military headcount without spiritual consequence.", "It shows that diplomacy had completely triumphed over warfare.", "It demonstrates that astrological positions determine all human destiny."]','"It reflects the psychological tension between righteous duty (Dharma) and emotional attachment (Moha)."','Chapter 1 lays bare the inner conflict of human consciousness before the dawn of higher wisdom.','Look for the answer highlighting inner consciousness and detachment over superficial attachment.',20);
INSERT INTO "questions" VALUES(672,47,'BG1.47',1,47,4,12,'life_scenario','advanced','Apply the wisdom of this verse to solve the dilemma','Scenario: A leader faces severe stress when a critical project faces turmoil. Remembering the teachings of Arjuna''s Dilemma, how should they respond?',NULL,'["Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes.", "Blame subordinates and walk away from the responsibility.", "Become paralyzed by fear of reputational loss.", "Promise unrealistic outcomes to temporarily placate critics."]','"Focus completely on performing their present responsibility with excellence, letting go of anxiety over outcomes."','The Bhagavad Gita teaches that excellence in action comes from inner composure and duty-consciousness rather than anxiety over results.','Reflect on how righteous detachment frees decision-making from personal bias.',20);
INSERT INTO "questions" VALUES(673,47,'BG1.47',1,47,4,13,'philosophical_insight','advanced','Uncover the inner allegorical meaning','What symbolic inner meaning is encapsulated within BG 1.47?',NULL,'["The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization.", "A passive acceptance of sorrow without any inner effort.", "A ritualistic sacrifice to attain temporary heavenly pleasures.", "A method to achieve material domination over others."]','"The perpetual inner transformation from ignorance (Avidya) to illuminating self-realization."','Every verse in the Gita serves as a beacon guiding the soul beyond egoic limitations towards inner liberation.','Think of the Gita as an internal dialogue within your own consciousness.',20);
INSERT INTO "questions" VALUES(674,47,'BG1.47',1,47,4,14,'true_false','beginner','Select the core life lesson','What is the ultimate life lesson to remember from BG 1.47?',NULL,'["True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma).", "One should always prioritize personal wealth and familial comfort over ethical duty.", "Inaction is superior to action in all circumstances.", "One should suppress emotions rather than understanding their root causes."]','"True wisdom begins by acknowledging one''s attachments and aligning every action with universal righteousness (Dharma)."','The Bhagavad Gita transforms crises into catalysts for spiritual awakening and ethical clarity.','Choose the principle that elevates character and universal well-being.',10);
INSERT INTO "verses" VALUES(1,1,1,'BG1.1','धृतराष्ट्र उवाच
INSERT INTO "verses" VALUES(2,1,2,'BG1.2','सञ्जय उवाच
INSERT INTO "verses" VALUES(3,1,3,'BG1.3','पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।
INSERT INTO "verses" VALUES(4,1,4,'BG1.4','अत्र शूरा महेष्वासा भीमार्जुनसमा युधि।
INSERT INTO "verses" VALUES(5,1,5,'BG1.5','धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान्।
INSERT INTO "verses" VALUES(6,1,6,'BG1.6','युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्।
INSERT INTO "verses" VALUES(7,1,7,'BG1.7','अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम।
INSERT INTO "verses" VALUES(8,1,8,'BG1.8','भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः।
INSERT INTO "verses" VALUES(9,1,9,'BG1.9','अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।
INSERT INTO "verses" VALUES(10,1,10,'BG1.10','अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।
INSERT INTO "verses" VALUES(11,1,11,'BG1.11','अयनेषु च सर्वेषु यथाभागमवस्थिताः।
INSERT INTO "verses" VALUES(12,1,12,'BG1.12','तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः।
INSERT INTO "verses" VALUES(13,1,13,'BG1.13','ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः।
INSERT INTO "verses" VALUES(14,1,14,'BG1.14','ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ।
INSERT INTO "verses" VALUES(15,1,15,'BG1.15','पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः।
INSERT INTO "verses" VALUES(16,1,16,'BG1.16','अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः।
INSERT INTO "verses" VALUES(17,1,17,'BG1.17','काश्यश्च परमेष्वासः शिखण्डी च महारथः।
INSERT INTO "verses" VALUES(18,1,18,'BG1.18','द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते।
INSERT INTO "verses" VALUES(19,1,19,'BG1.19','स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत्।
INSERT INTO "verses" VALUES(20,1,20,'BG1.20','अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः।
INSERT INTO "verses" VALUES(21,1,21,'BG1.21','अर्जुन उवाच
INSERT INTO "verses" VALUES(22,1,22,'BG1.22','यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान्।
INSERT INTO "verses" VALUES(23,1,23,'BG1.23','योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः।
INSERT INTO "verses" VALUES(24,1,24,'BG1.24','संजय उवाच
INSERT INTO "verses" VALUES(25,1,25,'BG1.25','भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्।
INSERT INTO "verses" VALUES(26,1,26,'BG1.26','तत्रापश्यत्स्थितान्पार्थः पितृ़नथ पितामहान्।
INSERT INTO "verses" VALUES(27,1,27,'BG1.27','श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि।
INSERT INTO "verses" VALUES(28,1,28,'BG1.28','अर्जुन उवाच
INSERT INTO "verses" VALUES(29,1,29,'BG1.29','सीदन्ति मम गात्राणि मुखं च परिशुष्यति।
INSERT INTO "verses" VALUES(30,1,30,'BG1.30','गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।
INSERT INTO "verses" VALUES(31,1,31,'BG1.31','निमित्तानि च पश्यामि विपरीतानि केशव।
INSERT INTO "verses" VALUES(32,1,32,'BG1.32','न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च।
INSERT INTO "verses" VALUES(33,1,33,'BG1.33','येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।
INSERT INTO "verses" VALUES(34,1,34,'BG1.34','आचार्याः पितरः पुत्रास्तथैव च पितामहाः।
INSERT INTO "verses" VALUES(35,1,35,'BG1.35','एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।
INSERT INTO "verses" VALUES(36,1,36,'BG1.36','निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन।
INSERT INTO "verses" VALUES(37,1,37,'BG1.37','तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान्।
INSERT INTO "verses" VALUES(38,1,38,'BG1.38','यद्यप्येते न पश्यन्ति लोभोपहतचेतसः।
INSERT INTO "verses" VALUES(39,1,39,'BG1.39','कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम्।
INSERT INTO "verses" VALUES(40,1,40,'BG1.40','कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः।
INSERT INTO "verses" VALUES(41,1,41,'BG1.41','अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।
INSERT INTO "verses" VALUES(42,1,42,'BG1.42','सङ्करो नरकायैव कुलघ्नानां कुलस्य च।
INSERT INTO "verses" VALUES(43,1,43,'BG1.43','दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः।
INSERT INTO "verses" VALUES(44,1,44,'BG1.44','उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन।
INSERT INTO "verses" VALUES(45,1,45,'BG1.45','अहो बत महत्पापं कर्तुं व्यवसिता वयम्।
INSERT INTO "verses" VALUES(46,1,46,'BG1.46','यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः।
INSERT INTO "verses" VALUES(47,1,47,'BG1.47','सञ्जय उवाच
